rentLoopData = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $day): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::startLoopIteration(); ?><?php endif; ?><option <?php if($schedule->day_of_week === $day): echo 'selected'; endif; ?>><?php echo e($day); ?></option><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::endLoop(); ?><?php endif; ?><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::closeLoop(); ?><?php endif; ?></select></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><label>Start time<input type="time" name="start_time" value="<?php echo e(substr($schedule->start_time, 0, 5)); ?>" required></label><label>End time<input type="time" name="end_time" value="<?php echo e(substr($schedule->end_time, 0, 5)); ?>" required></label></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><label>Building<input name="building" value="<?php echo e($schedule->building); ?>"></label><label>Room<input name="room_number" value="<?php echo e($schedule->room_number); ?>"></label></div><label>Trainee count<input type="number" name="student_count" min="0" value="<?php echo e($schedule->student_count); ?>"></label><label>Notes<textarea name="notes"><?php echo e($schedule->notes); ?></textarea></label><button class="btn" type="submit">Update schedule</button></form></div>
